import math

class Solution:
    def retrieve(self, query: list[float], documents: list[list[float]], k: int) -> list[int]:
        def cosine(vector):
            denominator=math.sqrt(sum(v*v for v in query)*sum(v*v for v in vector))
            return sum(a*b for a,b in zip(query,vector))/denominator if denominator else 0.0
        return sorted(range(len(documents)),key=lambda i:(-cosine(documents[i]),i))[:k]

